const input = $input.first().json;
const preparedAnswers = $('Prepare Answer').first().json.answer || [];

// Build answer map safely
const answerMap = new Map();
for (const item of preparedAnswers) {
  if (item?.number !== undefined) {
    answerMap.set(item.number, item.answer ?? null);
  }
}

const newQuestions = (input.questions || []).map(q => {
  const userAnswer = answerMap.has(q.number)
    ? answerMap.get(q.number)
    : null;

  const isCorrect = userAnswer === q.correctAnswer;

  return {
    ...q,
    answer: userAnswer,
    isCorrect: isCorrect
  };
});

// Calculate earned score
const totalScore = newQuestions.reduce((sum, q) => {
  return sum + (q.isCorrect ? (q.score || 0) : 0);
}, 0);

// Calculate full score
const fullScore = newQuestions.reduce((sum, q) => {
  return sum + (q.score || 0);
}, 0);

// Calculate percentage (0–100)
const percentageScore = fullScore > 0
  ? (totalScore / fullScore) * 100
  : 0;

// Optional: round to 2 decimal places
const finalPercentage = Math.round(percentageScore * 100) / 100;

return [
  {
    json: {
      exerciseId: input.exerciseId,
      questions: newQuestions,
      score: finalPercentage,
      submittedAt: new Date()
    }
  }
];

