const items = $input.all();
const studentsMap = {};

let totalCourses = 0;
let totalNormalStudents = 0;
let totalSlowStudents = 0;
let totalAtRiskStudents = 0;

const NOW = new Date();
const EXPECTED_DURATION_DAYS = 120;

// helper: คำนวณจำนวนวัน
function diffDays(date1, date2) {
  return Math.floor((date1 - date2) / (1000 * 60 * 60 * 24));
}

items.forEach(item => {
  const data = item.json;

  const userId = data.userId || "Unknown Student";

  if (!studentsMap[userId]) {
    studentsMap[userId] = {
      userId: userId,
      username: data.username ?? "Unknown",
      totalLessonsCompleted: 0,
      totalLessons: 0,
      courseAvgScoreSum: 0,
      courseCountWithScore: 0,
      courses: [],
      lastActive: null,
      delaySum: 0,
      courseCount: 0
    };
  } else if (studentsMap[userId].username == "Unknown") {
    studentsMap[userId].username = data.username ?? "Unknown"
  }

  totalCourses++;

  const courseTotalLessonsCompleted = data.totalLessonsCompleted || 0;
  const courseTotalLessons = data.totalLessons || 0;
  const courseAvgScore = data.avgScore || 0;
  const scores = data.scores || [];

  // ✅ fallback กัน null
  const createdAt = data.createdAt
    ? new Date(data.createdAt)
    : NOW;

  const updatedAt = data.updatedAt
    ? new Date(data.updatedAt)
    : data.lastActive
      ? new Date(data.lastActive)
      : data.createdAt
        ? new Date(data.createdAt)
        : NOW;

  const lessonTitles = data.outline && data.outline.lessons
    ? data.outline.lessons.map(l => l.title)
    : [];

  // =========================
  // ✅ PER COURSE CALCULATION
  // =========================

  const progressCourse = courseTotalLessons > 0
    ? (courseTotalLessonsCompleted / courseTotalLessons) * 100
    : 0;

  const daysSinceStart = diffDays(NOW, createdAt);

  const expectedProgress = (daysSinceStart / EXPECTED_DURATION_DAYS) * 100;

  const delayCourse = Math.max(0, expectedProgress - progressCourse);

  // =========================
  // ✅ AGGREGATE TO STUDENT
  // =========================

  studentsMap[userId].delaySum += delayCourse;
  studentsMap[userId].courseCount += 1;

  // lastActive = max(updatedAt)
  if (
    !studentsMap[userId].lastActive ||
    updatedAt > studentsMap[userId].lastActive
  ) {
    studentsMap[userId].lastActive = updatedAt;
  }

  studentsMap[userId].totalLessonsCompleted += courseTotalLessonsCompleted;
  studentsMap[userId].totalLessons += courseTotalLessons;

  if (data.avgScore !== undefined) {
    studentsMap[userId].courseAvgScoreSum += courseAvgScore;
    studentsMap[userId].courseCountWithScore += 1;
  }

  studentsMap[userId].courses.push({
    courseName: data.courseName,
    lessonIds: data.lessonIds || [],
    avgScore: courseAvgScore,
    totalLessonsCompleted: courseTotalLessonsCompleted,
    totalLessons: courseTotalLessons,
    scores: scores,
    outline: data.outline || {},
    createdAt: createdAt,
    updatedAt: updatedAt,
    progress: Number(progressCourse.toFixed(2)),
    delay: Number(delayCourse.toFixed(2))
  });
});

// =========================
// ✅ BUILD FINAL RESULT
// =========================

const studentsArray = Object.values(studentsMap).map(student => {

  const avgScore = student.courseCountWithScore > 0
    ? (student.courseAvgScoreSum / student.courseCountWithScore)
    : 0;

  const progress = student.totalLessons > 0
    ? (student.totalLessonsCompleted / student.totalLessons) * 100
    : 0;

  const delay = student.courseCount > 0
    ? (student.delaySum / student.courseCount)
    : 0;

  const daysSinceLastActive = student.lastActive
    ? diffDays(NOW, new Date(student.lastActive))
    : null;

  // =========================
  // ✅ STATUS LOGIC
  // =========================

  let status = "NORMAL";

  if (delay > 20 && daysSinceLastActive > 7) {
    status = "AT_RISK";
    totalAtRiskStudents++;
  } else if (delay > 10) {
    status = "SLOW";
    totalSlowStudents++;
  } else {
    totalNormalStudents++;
  }

  return {
    userId: student.userId,
    username: student.username,
    avgScore: Number(avgScore.toFixed(2)),
    totalLessonsCompleted: student.totalLessonsCompleted,
    totalLessons: student.totalLessons,
    progress: Number(progress.toFixed(2)),
    delay: Number(delay.toFixed(2)),
    lastActive: student.lastActive,
    daysSinceLastActive: daysSinceLastActive,
    status: status,
    courses: student.courses
  };
});

const finalResult = {
  totalStudents: studentsArray.length,
  totalCourses: totalCourses,
  totalNormalStudents,
  totalSlowStudents,
  totalAtRiskStudents,
  students: studentsArray
};

return [{ json: finalResult }];

