// 1. Grab the extracted text from the previous node.
const extractedText = $input.first().json.text || "";

// 2. Split the string into an array of pages.
let pages = extractedText.split('\f');

// 3. Fallback: If there is no \f, try splitting by double newline instead.
if (pages.length === 1) {
    pages = extractedText.split('\n\n');
}

// 4. Return each page as a brand new item, cleaning up the page numbers.
return pages.map((pageText, index) => {

    // First, trim standard excess whitespace
    let cleanedText = pageText.trim();

    // Use Regex to find and remove the trailing page number.
    // This looks for a gap/newline (\s+), optional dashes ([-]?\s*), 
    // an optional "Page " word ((?:Page\s*)?), and the digits (\d+) right at the end of the text ($)
    cleanedText = cleanedText.replace(/\s+[-]?\s*(?:Page\s*)?\d+\s*[-]?$/i, '');

    return {
        json: {
            pageNumber: index + 1,
            content: cleanedText.trim() // Trim one last time just to be safe
        }
    };
});
